nv/config -r tsconfig-paths/register ./examples/index.ts\"\n  },\n  \"resolutions\": {\n    \"@ant-design/icons\": \"^5.6.1\",\n    \"@formily/antd-v5\": \"1.2.3\",\n    \"@rushstack/ts-command-line\": \"4.23.7\",\n    \"@rspack/core\": \"1.7.8\",\n    \"@types/react\": \"18.3.18\",\n    \"@types/react-dom\": \"^18.0.0\",\n    \"@typescript-eslint/parser\": \"^6.2.0\",\n    \"**/@mongodb-js/zstd\": \"file:./packages/plugins/@nocobase/plugin-ai/npm-shims/@mongodb-js/zstd\",\n    \"**/node-liblzma\": \"file:./packages/plugins/@nocobase/plugin-ai/npm-shims/node-liblzma\",\n    \"react-router-dom\": \"^6.30.1\",\n    \"react-router\": \"^6.30.1\",\n    \"react\": \"^18.0.0\",\n    \"react-dom\": \"^18.0.0\",\n    \"nwsapi\": \"2.2.7\",\n    \"antd\": \"5.24.2\",\n    \"dayjs\": \"1.11.13\",\n    \"eslint\": \"8.57.1\",\n    \"**/@rushstack/node-core-library/ajv\": \"8.18.0\",\n    \"**/pm2/js-yaml\": \"4.3.2\",\n    \"**/request/uuid\": \"3.4.0\",\n    \"**/temp-write/uuid\": \"3.4.0\",\n    \"**/uuid\": \"11.1.1\",\n    \"**/qs\": \"6.16.0\"\n  },\n  \"config\": {\n    \"ghooks\": {\n      \"pre-commit\": \"yarn lint-staged && node ./scripts/addLicense.js\",\n      \"commit-msg\": \"commitlint --edit\"\n    }\n  },\n  \"lint-staged\": {\n    \"*.{js,json}\": [\n      \"prettier --write\"\n    ],\n    \"*.ts?(x)\": [\n      \"eslint --fix --cache --cache-location node_modules/.cache/eslint/\"\n    ]\n  },\n  \"devDependencies\": {\n    \"@alicloud/cdn20180510\": \"^4.2.2\",\n    \"@commitlint/cli\": \"^16.1.0\",\n    \"@commitlint/config-conventional\": \"^16.0.0\",\n    \"@commitlint/prompt-cli\": \"^16.1.0\",\n    \"@types/react\": \"18.3.18\",\n    \"@types/react-dom\": \"^18.0.0\",\n    \"ali-oss\": \"^6.1.0\",\n    \"auto-changelog\": \"^2.4.0\",\n    \"eslint-plugin-jest-dom\": \"^5.0.1\",\n    \"eslint-plugin-prettier\": \"^5.5.4\",\n    \"eslint-plugin-react\": \"^7.37.5\",\n    \"eslint-plugin-testing-library\": \"^5.11.0\",\n    \"ghooks\": \"^2.0.4\",\n    \"